import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { tabPanelStyles } from './tab-panel.styles.js';

/**
 * A panel of content associated with a `bl-tab`.
 *
 * @element bl-tab-panel
 * @slot - Panel content.
 * @csspart panel - The panel container.
 */
@customElement('bl-tab-panel')
export class BlTabPanel extends LitElement {
  static override styles = [tokens, tabPanelStyles];

  /** The value linking this panel to its tab. */
  @property()
  value = '';

  /** Whether this panel is currently active (visible). Managed by bl-tabs. */
  @property({ type: Boolean, reflect: true })
  active = false;

  private _panelId = `bl-tab-panel-${Math.random().toString(36).slice(2, 9)}`;

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'tabpanel');
    this.id = this.id || this._panelId;
    if (!this.hasAttribute('tabindex')) {
      this.setAttribute('tabindex', '0');
    }
  }

  /** Called by parent tabs to link to its tab. */
  setLabelledBy(tabId: string): void {
    if (tabId) {
      this.setAttribute('aria-labelledby', tabId);
    }
  }

  protected override render() {
    return html`
      <div class="panel" part="panel">
        <slot></slot>
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-tab-panel': BlTabPanel;
  }
}

import { css } from 'lit';

export const tabStyles = css`
  :host {
    display: inline-flex;
  }

  :host([aria-disabled='true']) {
    pointer-events: none;
    opacity: 0.5;
  }

  .tab {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--bl-spacing-xs);
    padding: var(--bl-spacing-sm) var(--bl-spacing-md);
    background: none;
    border: none;
    border-bottom: 2px solid transparent;
    cursor: pointer;
    font-family: var(--bl-font-family-base);
    font-size: var(--bl-font-size-sm);
    font-weight: 500;
    color: var(--bl-color-neutral-500);
    transition:
      color var(--bl-transition-fast),
      border-color var(--bl-transition-fast);
    white-space: nowrap;
  }

  .tab:hover {
    color: var(--bl-color-neutral-700);
  }

  :host([aria-selected='true']) .tab {
    color: var(--bl-color-primary-600);
    border-bottom-color: var(--bl-color-primary-600);
  }

  .tab:focus-visible {
    outline: 2px solid var(--bl-focus-ring-color);
    outline-offset: -2px;
    border-radius: var(--bl-radius-sm);
  }
`;

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { tabStyles } from './tab.styles.js';

/**
 * A single tab within a `bl-tabs` component.
 *
 * @element bl-tab
 * @slot - Tab label content.
 * @csspart tab - The tab button element.
 */
@customElement('bl-tab')
export class BlTab extends LitElement {
  static override styles = [tokens, tabStyles];

  /** The value linking this tab to its panel. */
  @property()
  value = '';

  /** Whether this tab is disabled. */
  @property({ type: Boolean })
  disabled = false;

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'tab');
    if (!this.hasAttribute('tabindex')) {
      this.setAttribute('tabindex', '-1');
    }
    this.addEventListener('click', this._handleClick);
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    this.removeEventListener('click', this._handleClick);
  }

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('disabled')) {
      this.setAttribute('aria-disabled', String(this.disabled));
    }
  }

  /** Called by parent tabs to update selection state. */
  setSelected(selected: boolean, panelId: string): void {
    this.setAttribute('aria-selected', String(selected));
    if (panelId) {
      this.setAttribute('aria-controls', panelId);
    }
  }

  private _handleClick = (): void => {
    if (this.disabled) return;
    this.dispatchEvent(
      new CustomEvent('bl-tab-select', {
        detail: { value: this.value },
        composed: true,
        bubbles: true,
      }),
    );
  };

  protected override render() {
    return html`
      <button
        class="tab"
        part="tab"
        tabindex="-1"
        @click=${this._handleClick}
      >
        <slot></slot>
      </button>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-tab': BlTab;
  }
}

import { css } from 'lit';

export const tabsStyles = css`
  :host {
    display: block;
  }

  .tablist {
    display: flex;
    border-bottom: 1px solid var(--bl-color-neutral-200);
    gap: 0;
  }

  :host([orientation='vertical']) .tablist {
    flex-direction: column;
    border-bottom: none;
    border-right: 1px solid var(--bl-color-neutral-200);
